// WF-03: compute a deterministic dedup key from a normalized phone.
const j = $input.first().json;
const phone = String(j.phone || j.normalized?.phone || '');
const email = String(j.email || j.normalized?.email || '').toLowerCase();

return [{ json: {
  ...j,
  __dedup: {
    phone,
    email,
    // production: use a NocoDB 'where' filter instead of fetching all rows:
    // GET /api/v2/tables/{id}/records?where=(phone,eq,{phone})
    lookup_key: phone || email,
  },
} }];

// WF-03: compare inbound lead against existing records and decide.
const inbound = $('Compute Lookup Key').first().json;
const key = inbound.__dedup.lookup_key;

let existing = null;
const rows = $input.first()?.json?.list || [];
for (const r of rows) {
  const p = String(r.phone || '');
  const e = String(r.email || '').toLowerCase();
  if ((key && p && p === key) || (key && e && e === key)) { existing = r; break; }
}

return [{ json: {
  inbound_phone: inbound.__dedup.phone,
  inbound_email: inbound.__dedup.email,
  is_duplicate: !!existing,
  existing_lead_id: existing ? existing.Id : null,
  existing_status: existing ? existing.status : null,
  action: existing ? 'UPDATE_EXISTING' : 'CREATE_NEW',
  note: 'Never overwrite lead history; append an Interaction to the existing lead on duplicate.',
} }];
